import sys
input = sys.stdin.readline

def solve():
	(N, M) = list(map(int, input().split()))
	X = []
	for i in range(M):
		X.append([])
	for i in range(N):
		K = list(map(int, input().split()))
		for j in range(M):
			X[j].append(K[j])
	flag = 0
	ans = set()
	Y = X.copy()
	for i in range(N):
		if flag:
			break
		for j in range(1, M):
			if X[j - 1][i] > X[j][i]:
				X.sort(key=lambda x: x[i])
				for l in range(M):
					if X[l][i] != Y[l][i]:
						ans.add(l + 1)
				continue
	for i in range(N):
		for j in range(1, M):
			if X[j - 1][i] > X[j][i]:
				print(-1)
				return
	if len(ans) == 0:
		print(1, 1)
	elif len(ans) >= 3:
		print(-1)
	else:
		print(*ans)
for _ in range(int(input())):
	solve()
